/* === numberToKoreanMoney (s3r86w8a.html L1877-1887) === */
function numberToKoreanMoney(n){
  n=Math.round(Number(n)||0);
  if(n<=0)return"";
  const digits="일이삼사오육칠팔구";
  const smallUnits=["","십","백","천"];
  const bigUnits=["","만","억","조"];
  const chunk4=(v)=>{let s="";for(let i=3;i>=0;i--){const d=Math.floor(v/Math.pow(10,i))%10;if(d)s+=(d===1&&i>0?"":digits[d-1])+smallUnits[i];}return s;};
  let result="";let bi=0;
  while(n>0){const c=n%10000;if(c)result=chunk4(c)+bigUnits[bi]+result;n=Math.floor(n/10000);bi++;}
  return result;
}

