/* === arapTravelFee (s3r86w8a.html L1958-1958) === */
function arapTravelFee(addr){
  // Official addresses split city and district; the fee table joins them without 시.
  const normalize=s=>String(s||'').replace(/\s+/g,'').replace(/^경기(?:도)?/,'경기도').replace(/^서울(?:특별시|시)?/,'서울특별시').replace(/시(?=[가-힣]+구)/g,'');
  const a=normalize(addr);let best=null,bl=0;
  for(const k in ARAP_TRAVEL_FEES){const key=normalize(k);if(a.indexOf(key)>=0&&key.length>bl){bl=key.length;best=ARAP_TRAVEL_FEES[k];}}
  return best;
}

/* === parseFeeStatement (s3r86w8a.html L1959-1972) === */
function parseFeeStatement(text){
  // 수수료 사이트 '계산서1 복사' 텍스트에서 항목별 금액 추출 — 라벨 뒤 첫 콤마숫자
  const pick=(label)=>{
    const line=(text||"").split("\n").find(l=>l.replace(/\s+/g," ").includes(label));
    if(!line)return null;
    const m=line.slice(line.indexOf(label.slice(-3))).match(/[\d,]{4,}/);
    return m?parseInt(m[0].replace(/,/g,""),10):null;
  };
  return{
    예상평가액:pick("예상평가액"),
    하한수수료:pick("하한 수수료"),기준수수료:pick("기준 수수료"),상한수수료:pick("상한 수수료"),
    하한총액:pick("하한 총액"),기준총액:pick("기준 총액"),상한총액:pick("상한 총액"),
  };
}

/* === computeCheonggu (s3r86w8a.html L1973-1987) === */
function computeCheonggu(fee,downPayment,specialFee,feeBasis,travelFee,surveyFee,docFee,etcFee){
  // 평가수수료=ROUNDDOWN(요율기준 수수료,-3) — 접수내용의 하한/기준/상한요율에 따름. 특별용역비=평가사 수동 결정값
  const rd=n=>Math.floor((n||0)/1000)*1000;
  const 평가수수료=rd(feeBasis==="기준"?fee.기준수수료:feeBasis==="상한"?fee.상한수수료:fee.하한수수료);
  const 특별용역비=parseInt(String(specialFee||"0").replace(/,/g,""),10)||0;
  const 여비=travelFee==null?40000:(parseInt(String(travelFee).replace(/,/g,""),10)||0);
  const 물건조사비=surveyFee==null?15000:(parseInt(String(surveyFee).replace(/,/g,""),10)||0),공부발급비=docFee==null?15000:(parseInt(String(docFee).replace(/,/g,""),10)||0),기타실비=etcFee==null?0:(parseInt(String(etcFee).replace(/,/g,""),10)||0);
  const 소계=여비+물건조사비+공부발급비+기타실비+특별용역비;
  const 합계=rd(평가수수료+소계);
  const 부가세=Math.round(합계*0.1);
  const 총계=합계+부가세;
  const 착수금=parseInt(String(downPayment||"0").replace(/,/g,""),10)||0;
  const 정산청구액=총계-착수금;
  return{평가수수료,여비,물건조사비,공부발급비,기타실비,특별용역비,소계,합계,부가세,총계,착수금,정산청구액};
}

/* === hwpxEsc (s3r86w8a.html L2394-2394) === */
// 날것 탭은 공백으로 — hwpx <hp:t> 안에 들어가면 한글이 뒤 글자를 먹는다
function hwpxEsc(s){return String(s==null?"":s).replace(/[\t\v\f]/g," ").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");}

/* === triggerDownload (s3r86w8a.html L2422-2427) === */
function triggerDownload(bytes,fname){
  const blob=new Blob([bytes],{type:"application/octet-stream"});const url=URL.createObjectURL(blob);
  const a=document.createElement("a");a.href=url;a.download=fname;
  document.body.appendChild(a);a.click();document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url),10000);
}

