const V2CHEONGGU_BLUE2BLACK={"49":"28","50":"41","51":"44","52":"45","53":"46"};

/* === buildTokenHwpx (s3r86w8a.html L2627-2643) === */
async function buildTokenHwpx(tplB64,tokenMap,blue2black){
  const bin=atob(tplB64);const arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);
  const entries=await parseZip(arr.buffer);
  if(!entries.length)throw new Error("hwpx 템플릿 파싱 실패");
  const mi=entries.findIndex(e=>e.name==="mimetype");if(mi>0){const[m]=entries.splice(mi,1);entries.unshift(m);} // hwpx는 mimetype이 zip 첫 항목이어야 함
  for(const e of entries){
    if(/^Contents\/section\d+\.xml$/.test(e.name)){
      let xml=new TextDecoder("utf-8").decode(e.data);
      for(const[tok,val]of Object.entries(tokenMap))xml=xml.split("{{"+tok+"}}").join(hwpxEsc(val));
      const left=[...new Set(xml.match(/\{\{[^}]+\}\}/g)||[])];
      if(left.length)console.warn("hwpx 미치환 토큰",e.name,left);
      for(const[b,k]of Object.entries(blue2black))xml=xml.split('charPrIDRef="'+b+'"').join('charPrIDRef="'+k+'"');
      e.data=new TextEncoder().encode(xml);
    }
  }
  return createZipStored(entries);
}

/* === inflate (s3r86w8a.html L2774-2784) === */
async function inflate(data){
  const ds=new DecompressionStream('deflate-raw');
  const w=ds.writable.getWriter();const r=ds.readable.getReader();
  w.write(data);w.close();
  const chunks=[];
  while(true){const{done,value}=await r.read();if(done)break;chunks.push(value);}
  const total=chunks.reduce((a,c)=>a+c.length,0);
  const out=new Uint8Array(total);let off=0;
  for(const c of chunks){out.set(c,off);off+=c.length;}
  return out;
}

/* === parseZip (s3r86w8a.html L2786-2804) === */
async function parseZip(buf){
  const view=new DataView(buf);const entries=[];let off=0;
  while(off<buf.byteLength-4){
    if(view.getUint32(off,true)!==0x04034b50)break;
    const method=view.getUint16(off+8,true);
    const compSz=view.getUint32(off+18,true);
    const uncompSz=view.getUint32(off+22,true);
    const nameLen=view.getUint16(off+26,true);
    const extraLen=view.getUint16(off+28,true);
    const name=new TextDecoder().decode(new Uint8Array(buf,off+30,nameLen));
    const dataOff=off+30+nameLen+extraLen;
    const raw=new Uint8Array(buf,dataOff,compSz);
    let data=raw;
    if(method===8&&compSz>0)try{data=await inflate(raw);}catch(e){data=raw;}
    entries.push({name,data,uncompSz});
    off=dataOff+compSz;
  }
  return entries;
}

/* === CRC32_TABLE (s3r86w8a.html L2807-2807) === */
const CRC32_TABLE=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0;}return t;})();

/* === crc32 (s3r86w8a.html L2808-2808) === */
function crc32(data){let c=0xFFFFFFFF;for(let i=0;i<data.length;i++)c=CRC32_TABLE[(c^data[i])&0xFF]^(c>>>8);return(c^0xFFFFFFFF)>>>0;}

/* === createZipStored (s3r86w8a.html L2809-2871) === */
function createZipStored(entries){
  let totalSz=0;
  const processed=entries.map(e=>{
    const nameBytes=new TextEncoder().encode(e.name);
    return{name:e.name,nameBytes,data:e.data,crc:crc32(e.data)};
  });
  // Calculate total size
  let sz=0;
  for(const e of processed)sz+=30+e.nameBytes.length+e.data.length+46+e.nameBytes.length;
  sz+=22;
  const out=new Uint8Array(sz);const dv=new DataView(out.buffer);
  let pos=0;const cdEntries=[];
  for(const e of processed){
    const localOff=pos;
    // Local file header
    dv.setUint32(pos,0x04034b50,true);pos+=4;
    dv.setUint16(pos,20,true);pos+=2; // version
    pos+=2; // flags
    pos+=2; // method=stored(0)
    pos+=2; // mod time
    pos+=2; // mod date
    dv.setUint32(pos,e.crc,true);pos+=4; // crc32
    dv.setUint32(pos,e.data.length,true);pos+=4; // comp size
    dv.setUint32(pos,e.data.length,true);pos+=4; // uncomp size
    dv.setUint16(pos,e.nameBytes.length,true);pos+=2;
    pos+=2; // extra len
    out.set(e.nameBytes,pos);pos+=e.nameBytes.length;
    out.set(e.data,pos);pos+=e.data.length;
    cdEntries.push({nameBytes:e.nameBytes,data:e.data,localOff,crc:e.crc});
  }
  const cdOff=pos;
  for(const c of cdEntries){
    dv.setUint32(pos,0x02014b50,true);pos+=4;
    dv.setUint16(pos,20,true);pos+=2; // version made
    dv.setUint16(pos,20,true);pos+=2; // version needed
    pos+=2; // flags
    pos+=2; // method=stored
    pos+=2; // time
    pos+=2; // date
    dv.setUint32(pos,c.crc,true);pos+=4; // crc32
    dv.setUint32(pos,c.data.length,true);pos+=4;
    dv.setUint32(pos,c.data.length,true);pos+=4;
    dv.setUint16(pos,c.nameBytes.length,true);pos+=2;
    pos+=2; // extra
    pos+=2; // comment
    pos+=2; // disk
    pos+=2; // internal attr
    pos+=4; // external attr
    dv.setUint32(pos,c.localOff,true);pos+=4;
    out.set(c.nameBytes,pos);pos+=c.nameBytes.length;
  }
  const cdSize=pos-cdOff;
  // EOCD
  dv.setUint32(pos,0x06054b50,true);pos+=4;
  dv.setUint16(pos,0,true);pos+=2; // disk number
  dv.setUint16(pos,0,true);pos+=2; // disk with CD
  dv.setUint16(pos,cdEntries.length,true);pos+=2;
  dv.setUint16(pos,cdEntries.length,true);pos+=2;
  dv.setUint32(pos,cdSize,true);pos+=4;
  dv.setUint32(pos,cdOff,true);pos+=4;
  dv.setUint16(pos,0,true);pos+=2; // comment len
  return out.slice(0,pos);
}
